{"command": "mkdir -p /tmp/tomltest && cat > /tmp/tomltest/Cargo.toml <<'EOF'
[package]
name = "tomltest"
version = "0.1.0"
edition = "2021"

[dependencies]
toml = "=1.1.2"
serde = { version = "1.0", features = ["derive"] }
EOF
cat /tmp/tomltest/Cargo.toml
mkdir -p /tmp/tomltest/src && cat > /tmp/tomltest/src/main.rs <<'EOF'
use serde::Deserialize;
use std::collections::BTreeMap;
#[derive(Deserialize, Debug)]
struct Config {
    #[serde(default)]
    scripts: BTreeMap<String, Script>,
    #[serde(default)]
    default: DefaultCfg,
}
#[derive(Deserialize, Debug)]
struct Script {
    command: String,
    description: Option<String>,
    tags: Option<Vec<String>>,
}
#[derive(Deserialize, Debug, Default)]
struct DefaultCfg {
    command_width: Option<usize>,
}
fn test(content: &str) {
    println!("=== content {:?} ===", content);
    match toml::from_str::<Config>(content) {
        Ok(c) => println!("OK: {:?}", c),
        Err(e) => println!("ERR: {}", e),
    }
}
fn main() {
    test("invalid toml [[[");
    test("[scripts.a]\ncommand = 123\n");
    test("[scripts.a]\ndescription = 'hi'\n");
    test("[scripts.a]\ncommand = 'hi'\n\n[default]\ncommand_width = 'not a number'\n");
    test("[scripts.a]\ncommand = 'hi'\ntags = 'not an array'\n");
    test("[scripts.a]\ncommand = 'hi'\ntags = [123]\n");
    test("[scripts.a]\ncommand = 'hi'\n\n[default]\ncommand_width = 10.5\n");
}
EOF
cd /tmp/tomltest && cargo run --offline 2>&1 | head -n 100
"}

