		if (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || ch == '_' {
			return "", tomlValue{}, fmt.Errorf("expected an equals, found an identifier at line %d", startLine)
		}
		// For other like '['? e.g., "invalid toml [[[" after "invalid", next is "toml" (identifier), so above.
		return "", tomlValue{}, fmt.Errorf("expected an equals, found an identifier at line %d", startLine)
	}
	p.advance() // consume '='
	p.skipWhitespace()
	// parse value
	val, err := p.parseValue()
	if err != nil {
		return "", tomlValue{}, err
	}
	// After value, skip whitespace/comments, expect newline or eof
	p.skipWhitespace()
	if !p.eof() && p.peek() == '#' {
		for !p.eof() && p.peek() != '\n' {
			p.advance()
		}
	}
	if !p.eof() && p.peek() != '\n' && p.peek() != '\r' {
		// trailing content? e.g., extra identifier? Original? For simplicity, error?
		// But for valid TOML, after value should be newline. If not, error.
		return "", tomlValue{}, fmt.Errorf("expected a newline, found an identifier at line %d", p.line)
	}
	return key, val, nil
}

func (p *tomlParser) parseValue() (tomlValue, error) {
	if p.eof() {
		return tomlValue{}, fmt.Errorf("expected a value at line %d", p.line)
	}
	c := p.peek()
	if c == '"' {
		// check for triple?
		if p.pos+2 < len(p.s) && p.s[p.pos+1] == '"' && p.s[p.pos+2] == '"' {
			return p.parseMultilineBasic()
		}
		return p.parseBasicString()
	}
	if c == '\'' {
		if p.pos+2 < len(p.s) && p.s[p.pos+1] == '\'' && p.s[p.pos+2] == '\'' {
			return p.parseMultilineLiteral()
		}
		return p.parseLiteralString()
	}
	if c == '[' {
		return p.parseArray()
	}
	if c == '{' {
		// inline table? Not needed for pier, but handle as error? For simplicity, parse as unknown?
		return tomlValue{}, fmt.Errorf("expected a value at line %d", p.line)
	}
	// bare value: number, boolean, etc. Read until whitespace, comment, newline, comma, ], }
	start := p.pos
	for !p.eof() {
		ch := p.peek()
		if ch == '\n' || ch == '\r' || ch == '#' || ch == ',' || ch == ']' || ch == '}' {
			break
		}
		if ch == ' ' || ch == '\t' {
			break
		}
		p.advance()
	}
	raw := strings.TrimSpace(p.s[start:p.pos])
	if raw == "" {
		return tomlValue{}, fmt.Errorf("expected a value at line %d", p.line)
	}
	// Determine type
	lower := strings.ToLower(raw)
	if lower == "true" || lower == "false" {
		return tomlValue{typ: "boolean", raw: raw}, nil
	}
	// Try integer?
	if isInteger(raw) {
		return tomlValue{typ: "integer", raw: raw}, nil
	}
	// Try float?
	if isFloat(raw) {
		return tomlValue{typ: "float", raw: raw}, nil
	}
	// Datetime? Ignore, treat as string? For error, treat as unknown?
	// For bare strings without quotes? In TOML, bare strings not allowed, but our parser will treat as error?
	// Original for "invalid toml [[["? That case is key-value with key "invalid", then expects "=", finds "toml", so error before value.
	// For other bare values like "command = hello"? "hello" without quotes is invalid TOML. What error does original give?
	// Likely "expected a value" or "invalid type"? Let's return generic.
	return tomlValue{}, fmt.Errorf("expected a value at line %d", p.line)
}

func isInteger(s string) bool {
	if s == "" {
		return false
	}
	// Allow leading +/-, underscores? Simplify: optional sign, digits, underscores?
	i := 0
	if s[0] == '+' || s[0] == '-' {
		i = 1
		if len(s) == 1 {
			return false
		}
	}
	// Check for hex, oct, bin? e.g., 0x, 0o, 0b? Those are integers too. For simplicity, if starts with 0x/0o/0b, treat as integer.
	if len(s)-i >= 2 && s[i] == '0' && (s[i+1] == 'x' || s[i+1] == 'X' || s[i+1] == 'o' || s[i+1] == 'b') {
		return true
	}
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			if s[i] != '_' {
				return false
			}
		}
	}
	return true
}
func isFloat(s string) bool {
	// Contains '.' or 'e'/'E' or 'inf'/'nan'?
	lower := strings.ToLower(s)
	if lower == "inf" || lower == "+inf" || lower == "-inf" || lower == "nan" || lower == "+nan" || lower == "-nan" {
		return true
	}
	hasDot := strings.Contains(s, ".")
	hasE := strings.Contains(strings.ToLower(s), "e")
	if hasDot || hasE {
		// Try parse as float?
		_, err := strconv.ParseFloat(strings.ReplaceAll(s, "_", ""), 64)
		return err == nil
	}
	return false
}

func (p *tomlParser) parseBasicString() (tomlValue, error) {
	// assumes peek=='"'
	startLine := p.line
	p.advance() // opening "
	var sb strings.Builder
	rawBuilder := strings.Builder{} // not needed
	for !p.eof() {
		c := p.peek()
		if c == '"' {
			p.advance()
			return tomlValue{typ: "string", raw: "", str: sb.String()}, nil
		}
		if c == '\n' || c == '\r' {
			return tomlValue{}, fmt.Errorf("expected a closing quote, found a newline at line %d", p.line)
		}
		if c == '\\' {
			p.advance()
			if p.eof() {
				return tomlValue{}, fmt.Errorf("expected a value at line %d", startLine)
			}
			esc := p.advance()
			switch esc {
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case '\\':
				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			case 'u':
				// \uXXXX
				if p.pos+4 > len(p.s) {
					return tomlValue{}, fmt.Errorf("expected a value at line %d", startLine)
				}
				hex := p.s[p.pos : p.pos+4]
				p.pos += 4
				n, err := strconv.ParseUint(hex, 16, 32)
				if err != nil {
					return tomlValue{}, fmt.Errorf("expected a value at line %d", startLine)
				}
				sb.WriteRune(rune(n))
			case 'U':
				if p.pos+8 > len(p.s) {
					return tomlValue{}, fmt.Errorf("expected a value at line %d", startLine)
				}
				hex := p.s[p.pos : p.pos+8]
				p.pos += 8
				n, err := strconv.ParseUint(hex, 16, 32)
				if err != nil {
					return tomlValue{}, fmt.Errorf("expected a value at line %d", startLine)
				}
				sb.WriteRune(rune(n))
			default:
				return tomlValue{}, fmt.Errorf("invalid escape at line %d", p.line)
			}
			_ = rawBuilder
		} else {
			// regular char (handle utf8)
			// Need to handle multibyte? Just advance one byte? For simplicity, handle runes.
			r, size := utf8.DecodeRuneInString(p.s[p.pos:])
			sb.WriteRune(r)
			p.pos += size
			if r == '\n' {
				p.line++
			}
		}
	}
	return tomlValue{}, fmt.Errorf("expected a closing quote at line %d", startLine)
}

func (p *tomlParser) parseLiteralString() (tomlValue, error) {
	startLine := p.line
	p.advance() // opening '
	var sb strings.Builder
	for !p.eof() {
		c := p.peek()
		if c == '\'' {
			p.advance()
			return tomlValue{typ: "string", str: sb.String()}, nil
		}
		if c == '\n' || c == '\r' {
			return tomlValue{}, fmt.Errorf("expected a closing quote, found a newline at line %d", p.line)
		}
		r, size := utf8.DecodeRuneInString(p.s[p.pos:])
		sb.WriteRune(r)
		p.pos += size
	}
	return tomlValue{}, fmt.Errorf("expected a closing quote at line %d", startLine)
}

