func (p *tomlParser) parseMultilineLiteral() (tomlValue, error) {
	startLine := p.line
	p.advance(); p.advance(); p.advance()
	if !p.eof() && p.peek() == '\n' {
		p.advance()
	} else if !p.eof() && p.peek() == '\r' {
		p.advance()
		if !p.eof() && p.peek() == '\n' {
			p.advance()
		}
	}
	var sb strings.Builder
	for !p.eof() {
		if p.pos+2 < len(p.s) && p.s[p.pos] == '\'' && p.s[p.pos+1] == '\'' && p.s[p.pos+2] == '\'' {
			p.advance(); p.advance(); p.advance()
			return tomlValue{typ: "string", str: sb.String()}, nil
		}
		r, size := utf8.DecodeRuneInString(p.s[p.pos:])
		sb.WriteRune(r)
		p.pos += size
		if r == '\n' {
			p.line++
		}
	}
	return tomlValue{}, fmt.Errorf("expected a closing quote at line %d", startLine)
}

func (p *tomlParser) parseArray() (tomlValue, error) {
	startLine := p.line
	p.advance() // '['
	var elems []tomlValue
	for {
		p.skipWhitespaceAndCommentsAndNewlinesArray()
		if p.eof() {
			return tomlValue{}, fmt.Errorf("expected a right bracket at line %d", startLine)
		}
		if p.peek() == ']' {
			p.advance()
			break
		}
		// parse value
		v, err := p.parseValue()
		if err != nil {
			return tomlValue{}, err
		}
		elems = append(elems, v)
		p.skipWhitespace()
		if !p.eof() && p.peek() == ',' {
			p.advance()
			continue
		}
		// no comma, expect ']' next loop
	}
	return tomlValue{typ: "array", arr: elems}, nil
}

func (p *tomlParser) skipWhitespaceAndCommentsAndNewlinesArray() {
	for !p.eof() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			p.advance()
		} else if c == '#' {
			for !p.eof() && p.peek() != '\n' {
				p.advance()
			}
		} else {
			break
		}
	}
