		sb.WriteString(fmt.Sprintf("[scripts.%s]\n", headerAlias))
		sb.WriteString(fmt.Sprintf("command = %s\n", encodeTomlString(script.Command)))
		if script.Description != nil {
			sb.WriteString(fmt.Sprintf("description = %s\n", encodeTomlString(*script.Description)))
		}
		if script.HasTags {
			if len(script.Tags) == 1 {
				sb.WriteString(fmt.Sprintf("tags = [%s]\n", encodeTomlString(script.Tags[0])))
			} else {
				sb.WriteString("tags = [\n")
