func formatRow(cells []string, widths []int) string {
	var sb strings.Builder
	sb.WriteString("⋮")
	for i, cell := range cells {
		sb.WriteString(" ")
		sb.WriteString(padRight(cell, widths[i]))
		sb.WriteString(" ⋮")
	}
	return sb.String()
