		}
		if tok == "-V" || tok == "--version" {
			printStdout(fmt.Sprintf("%s-copy 0.1.6\n", bin))
			return 0
		}
	}
	// Filter out "--" ?
	var positionals []string
	for _, tok := range rest {
		if tok == "--" {
			continue
		}
		if strings.HasPrefix(tok, "-") && tok != "-" {
