	}
	if len(positionals) == 0 {
		printStderr(fmt.Sprintf("error: The following required arguments were not provided:\n    <from-alias>\n    <to-alias>\n\nUSAGE:\n    %s copy <from-alias> <to-alias>\n\nFor more information try --help\n", bin))
		return 1
	}
	if len(positionals) == 1 {
		printStderr(fmt.Sprintf("error: The following required arguments were not provided:\n    <to-alias>\n\nUSAGE:\n    %s copy <from-alias> <to-alias>\n\nFor more information try --help\n", bin))
		return 1
	}
	if len(positionals) > 2 {
		printStderr(fmt.Sprintf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    %s copy <from-alias> <to-alias>\n\nFor more information try --help\n", positionals[2], bin))
		return 1
	}
	from, to := positionals[0], positionals[1]
	cfgPath, err := resolveReadPath(explicitConfig)
