	if err != nil {
		printStderr(fmt.Sprintf("error: %s\n", err.Error()))
		return 1
	}
	src, ok := cfg.Scripts[from]
	if !ok {
		printStderr(fmt.Sprintf("error: AliasNotFound: No script found by alias %s\n", from))
		return 1
	}
	if _, exists := cfg.Scripts[to]; exists {
		printStderr(fmt.Sprintf("error: AliasAlreadyExists:  %s\n", to))
		return 1
	}
	// Copy (deep)
	newScript := &Script{Command: src.Command, HasTags: src.HasTags, Tags: append([]string{}, src.Tags...)}
