	"os"
	"os/exec"
)

func getEditorName() string {
	if v, ok := getEnv("VISUAL"); ok && v != "" {
		return v
	}
	if v, ok := getEnv("EDITOR"); ok && v != "" {
		return v
	}
	return "vi"
}

func getEditorContent(initial string, bin string) (string, error) {
	editor := getEditorName()
	// Create temp file
	tmp, err := os.CreateTemp("", "pier_edit_*")
	if err != nil {
		return "", fmt.Errorf("EditorError: Failed when trying to get input from editor Failed to open `%s` as a text editor or editor was terminated with errors.", editor)
