import subprocess, os, tempfile
EXE_NEW="/tmp/my_pier"
EXE_OLD="/workspace/executable"
def run_old(*args, env_extra=None):
    env=os.environ.copy()
    if env_extra: env.update(env_extra)
    return subprocess.run([EXE_OLD]+list(args), capture_output=True, text=True, env=env)
def run_new(*args, env_extra=None):
    env=os.environ.copy()
    if env_extra: env.update(env_extra)
    return subprocess.run([EXE_NEW]+list(args), capture_output=True, text=True, env=env)

# Compare help
for args in [["--help"], ["-h"], ["--version"], ["-V"], ["add", "--help"], ["add", "-h"], ["list", "--help"], ["list", "-h"], ["help"], ["help", "add"]]:
    o=run_old(*args)
    n=run_new(*args)
    # Replace bin name? Both use different bin names (executable vs my_pier). For comparison, replace my_pier with executable in new output
    n_stdout=n.stdout.replace("my_pier", "executable")
    n_stderr=n.stderr.replace("my_pier", "executable")
    match = (o.stdout==n_stdout and o.stderr==n_stderr and o.returncode==n.returncode)
    print(f"{args} match={match}")
