import subprocess, os, tempfile
EXE_NEW="/tmp/my_pier"
EXE_OLD="/workspace/executable"
def run(exe, *args, env_extra=None):
    env=os.environ.copy()
    if env_extra: env.update(env_extra)
    return subprocess.run([exe]+list(args), capture_output=True, text=True, env=env)
with tempfile.TemporaryDirectory() as td:
    for exe,name in [(EXE_OLD,"OLD"),(EXE_NEW,"NEW")]:
        cfg=os.path.join(td,f"pier_{name}.toml")
